CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, ip_address inet, timestamp timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,user_id) REFERENCES users(organization_id,id)); CREATE INDEX audit_org_time_idx ON audit_logs(organization_id,timestamp DESC);
